 "content": "def transform(grid):
    """Advance each 4 one row downward; a 4 arriving immediately above
    the 2-barrier fans diagonally upward to the top edge."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    barriers = [r for r, row in enumerate(grid) if row and all(v == 2 for v in row)]
    barrier = barriers[0] if barriers else None
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    for r, c in markers:
        out[r][c] = 0
    for r, c in markers:
        nr = min(r + 1, h - 1)
        if barrier is not None and nr == barrier:
            # Preserve the barrier rather than placing a marker over it.
            nr = r
        out[nr][c] = 4
        if barrier is not None and nr == barrier - 1:
            for d in range(1, nr + 1):
                rr = nr - d
                for cc in (c - d, c + d):
                    if 0 <= cc < w:
                        out[rr][cc] = 4
    return out
